function leadingSelfcheck(){const s=LEADING_SPECS[2],shape={signature:'P,P',priceNote:[0],closing:[1],rows:2},article=body=>Buffer.from(`<article class="article"><section class="article-hero"><div class="article-hero-copy"><p>I</p></div></section>${body}</article>`),valid='<table class="price-table"><thead><tr><th>Услуга</th><th>Цена, руб.</th></tr></thead><tbody><tr><td>A</td><td>от 100</td></tr><tr><td>B</td><td>1500</td></tr></tbody></table><p class="price-note">N</p><div class="closing"><p>C</p></div>',expect=(code,fn)=>{try{fn();fail('SELFCHECK_EXPECTED_FAILURE')}catch(e){if(e.code!==code)throw e}};const x=leadingArtifactFacts(article(valid),{...s,map_id:'MAP-055'},shape);if(x.price_rows.length!==2||x.price_rows.some(row=>row.cell.kind!=='amount')||x.blocks.length!==2)fail('SELFCHECK_PARSE');expect('ARTIFACT_PRICE',()=>leadingArtifactFacts(article(valid.replace('от 100','100 руб.')),{...s,map_id:'MAP-055'},shape));expect('ARTIFACT_GRAMMAR',()=>leadingArtifactFacts(article(valid.replace('<table class="price-table">','<p>X</p><table class="price-table">')),{...s,map_id:'MAP-055'},shape));const expected=buildLeading();if(expected.pages.length!==5||expected.pages.reduce((n,p)=>n+p.price_rows.length,0)!==46||expected.pages[2].price_rows.filter(row=>row.cell.kind==='text').length!==2)fail('SELFCHECK_PACKAGE');const changed=structuredClone(expected);changed.pages[0].price_rows.reverse();expect('PACKAGE_CONTENT',()=>exactPackage(changed,expected));process.stdout.write('{"schema":"dev09-leading-price-details-selfcheck-v1","status":"pass"}\n')}
