function diagnosticsSelfcheck(){const expect=(code,fn)=>{try{fn();fail('SELFCHECK_EXPECTED_FAILURE')}catch(e){if(e.code!==code)throw e}},expected=buildDiagnostics();if(expected.pages.length!==10||expected.pages[0].map_id!=='MAP-013'||expected.pages[0].source_table.rows.length!==6||expected.pages.slice(1).some(x=>'source_table' in x))fail('SELFCHECK_PACKAGE');const source=text(pinnedSized(DIAGNOSTICS_SPECS[0].source,DIAGNOSTICS_SPECS[0].sourceBytes,DIAGNOSTICS_SPECS[0].sourceSha),'SOURCE_UTF8');expect('SOURCE_TABLE',()=>diagnosticsSourceTable(Buffer.from(source.replace('Цена, руб.','Цена'))));expect('SOURCE_TABLE',()=>diagnosticsSourceTable(Buffer.from(source.replace('<div class="c-content">','<div class="c-content"><p>before</p>'))));expect('SOURCE_TABLE',()=>diagnosticsSourceTable(Buffer.from(source.replace('</table>','</table><table><tbody><tr><td>extra</td></tr></tbody></table>'))));expect('SOURCE_TABLE',()=>diagnosticsSourceTable(Buffer.from(source.replace('</table>','</table><TABLE><TBODY><TR><TD>extra</TD></TR></TBODY></TABLE>'))));const artifact=text(pinnedSized(DIAGNOSTICS_SPECS[0].artifact,DIAGNOSTICS_SPECS[0].artifactBytes,DIAGNOSTICS_SPECS[0].artifactSha),'ARTIFACT_UTF8'),authority=diagnosticsCatalogFacts(pinned(CATALOG,CATALOG_SHA));expect('ARTIFACT_BOUNDARY',()=>diagnosticsArtifactFacts(Buffer.from(artifact.replace('<article class="article">','<p>extra root</p><article class="article">')),DIAGNOSTICS_SPECS[0],DIAGNOSTICS_SHAPES.get('MAP-013'),authority.group));for(const changed of [artifact.replace('<span>01</span>','<span>00</span>'),artifact.replace('Диагностика перед приобретением','Другое название'),artifact.replace('/diagnostirovanie-avto-pered-priobreteniem','/wrong'),artifact.replace('<nav class="service-grid"','<nav class="other"')])expect('ARTIFACT_NAV',()=>diagnosticsArtifactFacts(Buffer.from(changed),DIAGNOSTICS_SPECS[0],DIAGNOSTICS_SHAPES.get('MAP-013'),authority.group,false));const child=DIAGNOSTICS_SPECS[1],article=body=>Buffer.from(`<article class="article"><section class="article-hero"><div class="article-hero-copy"><p>I</p></div></section>${body}</article>`),shape={signature:'H,P,P',closing:[2]},valid='<h2>H</h2><p>A</p><div class="closing"><p>Z</p></div>';for(const body of ['<h2>H</h2><div class="closing"><p>Z</p></div>',valid+'<p>X</p>','<p>A</p><h2>H</h2><div class="closing"><p>Z</p></div>',valid.replace('class="closing"','class="other"'),valid.replace('<p>A</p>','<p>A</p><table><tbody><tr><td>X</td></tr></tbody></table>')])expect('ARTIFACT_GRAMMAR',()=>diagnosticsArtifactFacts(article(body),child,shape,authority.group,false));for(const mutate of [v=>v.pages.pop(),v=>v.pages[0].blocks.reverse(),v=>v.pages[0].source_table.rows.reverse(),v=>v.pages[1].source_table={headers:[],rows:[]}]){const changed=structuredClone(expected);mutate(changed);expect('PACKAGE_CONTENT',()=>exactPackage(changed,expected))}process.stdout.write('{"schema":"dev09-diagnostics-branch-selfcheck-v1","status":"pass"}\n')}
function checkDiagnostics(){const expected=buildDiagnostics(),b=read(DIAGNOSTICS_PACKAGE);if(DIAGNOSTICS_PACKAGE_SHA==='__DIAGNOSTICS_PACKAGE_SHA__'||digest(b)!==DIAGNOSTICS_PACKAGE_SHA)fail('PACKAGE_SHA256');const actual=parsePackage(b);exactPackage(actual,expected);process.stdout.write(`${JSON.stringify({schema:'dev09-diagnostics-branch-check-v1',status:'pass',pages:10,table_rows:6,bytes:b.length,writes:0,published:0})}\n`)}
try{const mode=process.argv[2];if(mode==='--emit')process.stdout.write(canonical(build()));else if(mode==='--selfcheck')selfcheck();else if(mode==='--check')check();else if(mode==='--emit-planned-maintenance')process.stdout.write(canonical(buildPlanned()));else if(mode==='--selfcheck-planned-maintenance')plannedSelfcheck();else if(mode==='--check-planned-maintenance')checkPlanned();else if(mode==='--emit-leading-prices')process.stdout.write(canonical(buildLeading()));else if(mode==='--selfcheck-leading-prices')leadingSelfcheckExtended();else if(mode==='--check-leading-prices')checkLeading();else if(mode==='--emit-diagnostics')process.stdout.write(canonical(buildDiagnostics()));else if(mode==='--selfcheck-diagnostics')diagnosticsSelfcheck();else if(mode==='--check-diagnostics')checkDiagnostics();else fail('USAGE')}catch(e){process.stderr.write(`${e.code||'VALIDATION_FAILED'}\n`);process.exitCode=1}
